"""Optional oracle bridge for traces generated by AgentTelemetry's fault harness.

Set ``AGENTTELEMETRY_ROOT`` to an AgentTelemetry checkout before running a
Chrolo dataset benchmark built by ``benchmarks/build_agenttelemetry_dataset.py``.
This evaluates preservation of AgentTelemetry's rule-based fault-detection
signal over telemetry spans; it does not claim to reproduce the agent task.
"""
from __future__ import annotations

import os
import sys
import importlib.util
from pathlib import Path
from typing import Any

from .core import Event


def _detector(condition: str):
    root_value = os.environ.get("AGENTTELEMETRY_ROOT")
    if not root_value:
        raise RuntimeError("Set AGENTTELEMETRY_ROOT to the AgentTelemetry repository")
    root = Path(root_value).resolve()
    if not (root / "benchmarks" / "run_benchmarks.py").is_file():
        raise RuntimeError("AGENTTELEMETRY_ROOT must point to an AgentTelemetry checkout")
    for entry in (root / "src", root):
        value = str(entry)
        if value in sys.path:
            sys.path.remove(value)
        sys.path.insert(0, value)

    from benchmarks.faults import FaultType
    from benchmarks.run_benchmarks import (
        _analyze_traces,
        _analyze_traces_genai,
        _analyze_traces_openinference,
        _analyze_traces_vanilla,
    )

    analyzers = {
        "agenttelemetry": _analyze_traces,
        "vanilla_otel": _analyze_traces_vanilla,
        "otel_genai": _analyze_traces_genai,
        "openinference": _analyze_traces_openinference,
    }

    analyzer = analyzers.get(condition)
    if analyzer is None:
        raise ValueError(f"Unsupported AgentTelemetry condition: {condition}")
    return analyzer, FaultType


def _load_generator():
    root_value = os.environ.get("AGENTTELEMETRY_ROOT")
    if not root_value:
        raise RuntimeError("Set AGENTTELEMETRY_ROOT to the AgentTelemetry repository")
    root = Path(root_value).resolve()
    path = root / "src" / "agenttelemetry_inspect" / "generate_dataset.py"
    if not path.is_file():
        raise RuntimeError("AGENTTELEMETRY_ROOT must point to an AgentTelemetry checkout")
    spec = importlib.util.spec_from_file_location("agenttelemetry_generator_for_chrolo", path)
    if spec is None or spec.loader is None:
        raise RuntimeError(f"Cannot load AgentTelemetry generator at {path}")
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    return module


def analyze_trace(events: list[Event]) -> dict[str, Any]:
    """Run the original deterministic detector against a minimized span list."""
    context_events = [event for event in events if event.kind == "scenario"]
    if len(context_events) != 1:
        raise ValueError("Candidate must retain exactly one benchmark scenario event")
    context = context_events[0].payload
    analyzer, fault_type_enum = _detector(str(context["condition"]))
    fault_type = fault_type_enum(context["fault_type"])
    spans = [event.payload for event in events if event.kind == "span"]
    detected, _, _, _ = analyzer(spans, fault_type, context["ground_truth"])
    return {
        "detected": bool(detected),
        "failure_signature": str(context["fault_type"]) if detected else None,
        "expected_signature": str(context["fault_type"]),
    }


def preserves_injected_fault(result: dict[str, Any]) -> bool:
    """Oracle: the same injected-fault detector still fires after reduction."""
    return bool(
        result.get("detected")
        and result.get("failure_signature") == result.get("expected_signature")
    )


def run_without_injected_fault(events: list[Event]) -> dict[str, Any]:
    """Re-run the same deterministic mock scenario with AgentTelemetry's injector disabled."""
    context_events = [event for event in events if event.kind == "scenario"]
    if len(context_events) != 1:
        raise ValueError("Candidate must retain exactly one benchmark scenario event")
    context = context_events[0].payload
    analyzer, fault_type_enum = _detector(str(context["condition"]))
    generator = _load_generator()
    fault_type = fault_type_enum(context["fault_type"])
    spans, _, result = generator._run_cell(
        str(context["condition"]),
        str(context["framework"]),
        generator.FaultType.NONE,
        task=str(context["task"]),
    )
    if result.get("error"):
        raise RuntimeError("Fault-disabled reference scenario failed")
    detected, _, _, _ = analyzer(spans, fault_type, [])
    return {
        "detected": bool(detected),
        "failure_signature": str(context["fault_type"]) if detected else None,
        "expected_signature": str(context["fault_type"]),
    }
